{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Contact — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Reach {{PRACTITIONER_NAME}} for personalized aromatherapy guidance, membership details, blends & safe usage notes." />
  <style>
    :root{
      --bg-cream:#FEF7F0;
      --terracotta:#B55A3F;
      --deep-terra:#873E2A;
      --sage:#6B8B6F;
      --olive:#7A927A;
      --warm-gray:#6B5F56;
      --muted:#A79B92;
      --glass: rgba(255,255,255,0.72);
      --card-shadow: 0 8px 30px rgba(21,18,16,0.12);
      font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
    }
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg-cream) 0%, #FFFDFB 100%);color:var(--deep-terra);}
    .wrap{min-height:100vh;display:flex;flex-direction:column;}

    /* Background pattern (prefers local asset then inline SVG) */
    .page-bg{
      position:fixed;inset:0;z-index:-2;opacity:0.95;pointer-events:none;
      background-image: url('assets/img/pattern.svg');
      background-repeat:repeat; background-size:450px;
      mix-blend-mode:multiply; filter:contrast(0.98) saturate(0.95);
    }
    /* Inline decorative svg fallback */
    .svg-fallback{position:fixed;inset:0;z-index:-3;opacity:0.22;pointer-events:none}

    header{display:flex;align-items:center;justify-content:space-between;padding:28px 36px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo-mark{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,var(--terracotta),var(--sage));display:flex;align-items:center;justify-content:center;color:ivory;font-weight:700;box-shadow:var(--card-shadow)}
    .brand h1{font-size:18px;margin:0;color:var(--deep-terra)}
    nav a{color:var(--warm-gray);text-decoration:none;margin:0 10px;font-weight:600}
    nav a.current{color:var(--deep-terra);}

    main{flex:1;display:grid;grid-template-columns:1fr;gap:28px;padding:18px 22px 80px;max-width:1100px;margin:0 auto;width:100%}

    .hero{background:linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.6));border-radius:14px;padding:28px;display:flex;gap:24px;align-items:center;box-shadow:var(--card-shadow)}
    .hero .left{flex:1}
    .hero h2{margin:0 0 8px 0;font-size:28px;color:var(--deep-terra)}
    .hero p{margin:0;color:var(--warm-gray);line-height:1.5}
    .cta-row{margin-top:16px;display:flex;gap:12px;align-items:center}
    .btn{display:inline-block;padding:10px 16px;border-radius:10px;background:linear-gradient(90deg,var(--terracotta),var(--deep-terra));color:#fff;text-decoration:none;font-weight:700;box-shadow:0 6px 18px rgba(136,64,50,0.18)}
    .btn.ghost{background:transparent;color:var(--deep-terra);border:1px solid rgba(120,90,80,0.08);box-shadow:none}

    .contact-grid{display:grid;grid-template-columns:1fr 420px;gap:22px}
    .panel{background:var(--glass);backdrop-filter:blur(6px);padding:18px;border-radius:12px;box-shadow:var(--card-shadow)}

    form label{display:block;font-size:13px;color:var(--warm-gray);margin-bottom:6px}
    input[type=text],input[type=email],input[type=tel],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(120,90,80,0.08);font-size:14px;color:var(--deep-terra);background:#fff}
    textarea{min-height:120px;resize:vertical}
    .small{font-size:13px;color:var(--muted)}

    .meta{display:flex;flex-direction:column;gap:12px}
    .meta .info{display:flex;gap:12px;align-items:center}
    .pill{background:linear-gradient(90deg,var(--olive),var(--sage));color:#fff;padding:6px 8px;border-radius:999px;font-size:13px}

    footer{padding:28px 36px;background:transparent;border-top:1px solid rgba(120,90,80,0.04);display:flex;justify-content:space-between;align-items:center}
    .legal{color:var(--muted);font-size:13px}

    /* Responsive */
    @media (max-width:920px){
      .contact-grid{grid-template-columns:1fr}
      header{padding:18px}
      .hero{flex-direction:column;align-items:flex-start}
    }
  </style>
</head>
<body>
  <div class="wrap">
    <div class="page-bg" aria-hidden="true"></div>
    <svg class="svg-fallback" viewBox="0 0 1000 600" preserveAspectRatio="none">
      <defs>
        <linearGradient id="g1" x1="0" x2="1">
          <stop offset="0%" stop-color="#FFF6F1" />
          <stop offset="100%" stop-color="#F7F9F5" />
        </linearGradient>
        <pattern id="dots" x="0" y="0" width="120" height="120" patternUnits="userSpaceOnUse">
          <rect width="120" height="120" fill="url(#g1)" />
          <circle cx="18" cy="20" r="2.6" fill="#EAD6C9" opacity="0.9" />
          <circle cx="72" cy="92" r="2.6" fill="#D7E7DA" opacity="0.85" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#dots)" />
    </svg>

    <header>
      <div class="brand">
        <div class="logo-mark">A</div>
        <div>
          <h1>{{BUSINESS_NAME}}</h1>
          <div class="small">Curated aromatics & seasonal rituals</div>
        </div>
      </div>
      <nav aria-label="Primary">
        <a href="/index.html">Home</a>
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Boutique</a>
        <a href="/pricing.html">Membership</a>
        <a href="/about.html">About</a>
        <a href="/book.html">Book</a>
        <a class="current" href="/contact.html">Get in Touch</a>
      </nav>
    </header>

    <main>
      <section class="hero" aria-labelledby="hero-heading">
        <div class="left">
          <h2 id="hero-heading">Warm, careful guidance for everyday ritual</h2>
          <p>Hi — I’m {{PRACTITIONER_NAME}}. I listen first, then craft gentle aromatic blends and routines that fit your life. Please note: aromatherapy supports wellbeing practices but is not a substitute for medical care.</p>
          <div class="cta-row">
            <a class="btn" href="/book.html">Request a session</a>
            <a class="btn ghost" href="/pricing.html">Explore membership</a>
          </div>
        </div>
        <div class="right">
          <div style="display:flex;flex-direction:column;gap:10px;align-items:flex-end">
            <div class="pill">Serving {{CITY}}, {{STATE}}</div>
            <div class="panel" style="width:300px;text-align:right">
              <div style="font-weight:700;color:var(--deep-terra)">{{BUSINESS_NAME}}</div>
              <div class="small">Call: <a href="tel:{{PHONE}}" style="color:var(--deep-terra);text-decoration:none">{{PHONE}}</a></div>
              <div class="small">Email: <a href="mailto:{{EMAIL}}" style="color:var(--deep-terra);text-decoration:none">{{EMAIL}}</a></div>
            </div>
          </div>
        </div>
      </section>

      <section class="contact-grid">
        <div class="panel" aria-labelledby="contact-form-heading">
          <h3 id="contact-form-heading" style="margin-top:0">Write a note — I’ll reply within 2 business days</h3>
          <form id="contactForm" novalidate>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
              <div>
                <label for="name">Your name</label>
                <input id="name" name="name" type="text" placeholder="First & last" required />
              </div>
              <div>
                <label for="phone">Phone</label>
                <input id="phone" name="phone" type="tel" placeholder="(optional)" />
              </div>
            </div>
            <div style="margin-top:12px">
              <label for="email">Email</label>
              <input id="email" name="email" type="email" placeholder="the best email to reach you" required />
            </div>

            <div style="margin-top:12px">
              <label for="interest">What are you interested in?</label>
              <select id="interest" name="interest">
                <option>One-on-one consultation</option>
                <option>Custom blended oils</option>
                <option>Gift set or kit</option>
                <option>Membership plan</option>
                <option>Wholesale / partnership</option>
              </select>
            </div>

            <div style="margin-top:12px">
              <label for="message">Message</label>
              <textarea id="message" name="message" placeholder="Tell me about your routine, preferences, or questions" required></textarea>
            </div>

            <div style="display:flex;gap:12px;align-items:center;margin-top:12px">
              <label style="display:flex;gap:8px;align-items:center"><input type="checkbox" id="membershipCheck" name="membership" /> <span class="small">I’m curious about membership benefits</span></label>
              <div style="flex:1" class="small">If yes, I’ll include an overview of our seasonal blends & member-only rituals.</div>
            </div>

            <div style="margin-top:12px" class="small">
              <label style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" required /> I have read the safety notes and understand aromatherapy is supportive, not medical advice.</label>
            </div>

            <div style="margin-top:14px;display:flex;gap:10px;align-items:center">
              <button class="btn" type="submit" aria-label="Send message">Send message</button>
              <a class="btn ghost" href="mailto:{{EMAIL}}">Email directly</a>
            </div>

            <div id="formMsg" aria-live="polite" style="margin-top:12px;color:var(--sage);"></div>
          </form>

          <hr style="border:none;border-top:1px solid rgba(120,90,80,0.06);margin:18px 0" />

          <div class="small">
            Quick notes on safety & next steps:
            <ul style="margin:8px 0 0 18px">
              <li>Always dilute essential oils appropriately; typical adult dilutions are 1–3% for leave-on blends. For children, older adults, and pregnancy, use lower dilutions and consult a trusted healthcare provider.</li>
              <li>Perform a patch test before regular topical use — apply diluted blend to a small area and observe 24 hours for sensitivity.</li>
              <li>Keep oils away from pets' noses and food bowls; some essential oils are not safe for animals. Mention any pets when we speak.</li>
              <li>For pregnancy, breastfeeding, or complex medical conditions, please consult your clinician before use. I will provide safety-forward recommendations during our consultation.</li>
            </ul>
          </div>
        </div>

        <aside class="panel" aria-labelledby="help-heading">
          <h4 id="help-heading">Other ways to connect</h4>
          <div class="meta" style="margin-top:8px">
            <div class="info"><strong style="width:90px;display:inline-block">Phone</strong> <span>{{PHONE}}</span></div>
            <div class="info"><strong style="width:90px;display:inline-block">Email</strong> <span>{{EMAIL}}</span></div>
            <div class="info"><strong style="width:90px;display:inline-block">Visit</strong> <span>{{CITY}}, {{STATE}}</span></div>
            <div style="padding-top:6px" class="small">If you are a member, please sign in to your portal for priority slots. New to membership? <a href="/pricing.html">See plans</a>.</div>
          </div>

          <hr style="border:none;border-top:1px solid rgba(120,90,80,0.06);margin:14px 0" />

          <div>
            <h5 style="margin:6px 0 8px 0">Quick membership snapshot</h5>
            <p class="small">Our membership blends monthly seasonal roll-outs, quarterly ritual guides, and 10% off bespoke blends. Memberships are supportive, community-focused, and safety-first.</p>
            <a class="btn" href="/pricing.html">Join the circle</a>
          </div>

          <hr style="border:none;border-top:1px solid rgba(120,90,80,0.06);margin:14px 0" />

          <div class="small">
            • Response time: typically within 48 hours during business days.
            <br />• If this is urgent, please call: <a href="tel:{{PHONE}}">{{PHONE}}</a>
          </div>
        </aside>
      </section>
    </main>

    <footer>
      <div class="legal">&copy; <span id="year"></span> {{BUSINESS_NAME}} — Stories in scent by {{PRACTITIONER_NAME}}</div>
      <div>
        <a href="/about.html" class="small">About</a> &nbsp;•&nbsp; <a href="/blends.html" class="small">Blends</a> &nbsp;•&nbsp; <a href="/shop.html" class="small">Shop</a>
      </div>
    </footer>
  </div>

  <script>
    (function(){
      document.getElementById('year').textContent = new Date().getFullYear();
      var form = document.getElementById('contactForm');
      var msg = document.getElementById('formMsg');
      form.addEventListener('submit', function(e){
        e.preventDefault();
        var name = form.name.value.trim();
        var email = form.email.value.trim();
        if(!name || !email){
          msg.textContent = 'Please provide your name and email so I can reply.';
          return;
        }
        // Simulated submit — in production wire to your endpoint or mailer
        msg.textContent = 'Thanks, ' + (name.split(' ')[0] || '') + '. I will reply within two business days. If urgent, please call ' + '{{PHONE}}' + '.';
        form.querySelector('button[type="submit"]').disabled = true;
        form.reset();
      });
    })();
  </script>
</body>
</html>"} 
